import { createRequire } from "node:module";
import { dirname, relative } from "node:path";
import { fileURLToPath } from "node:url";

const importer = fileURLToPath(import.meta.url);
const root = dirname(dirname(dirname(importer)));
const load = createRequire(import.meta.url);

function show(resolved) {
  return resolved.startsWith("/") || /^[A-Za-z]:\\/.test(resolved) ? relative(root, resolved).replaceAll("\\", "/") : resolved;
}

function describe(resolve, request) {
  try {
    return show(resolve(request));
  } catch (error) {
    return `${error.name} ${error.code}: ${error.message.replaceAll(importer, "<importer>")}`;
  }
}

const requests = [
  "fs",
  "node:fs",
  "node:test",
  "./data.json",
  "./data",
  "./index",
  "resolve-probe",
  "resolve-probe/data",
  "with-exports",
  "with-exports/feature",
  "with-exports/lib/helper",
  "with-main",
  "plain-index",
  "@scope/scoped",
  "./missing",
  "scriptc-corpus-missing-package",
  "",
  42,
];

export function resolveAll(options = {}) {
  const resolve = options.resolve ?? load.resolve;
  const label = (request) => (typeof request === "string" ? JSON.stringify(request) : String(request));
  return [
    ...requests.map((request) => `call ${label(request)} -> ${describe((r) => load.resolve(r), request)}`),
    ...requests.slice(0, 4).map((request) => `value ${label(request)} -> ${describe(resolve, request)}`),
    `options ${describe((r) => load.resolve(r, {}), "with-main")}`,
  ];
}
